def _session(root, fn):
    log = []
    with tempfile.TemporaryDirectory() as td:
        project = Path(td); source = project / 'episode.json'; source.write_text('{}', encoding='utf-8')
        desktop = SimpleNamespace(win=root, root=project, video=None, current_frame_json=lambda: source,
                                  cloud_settings_window=None)
        fn(desktop); root.update()
        win = desktop.cloud_settings_window
        steps = drive(win, [td], log, skip=('测试连接', '显示已保存密钥（10 秒）'))
        steps.append(('files', sorted(str(p.relative_to(project)) for p in project.rglob('*'))))
        if win.winfo_exists():
            win.destroy()
    return steps


class CloudSettingsWindowEquivalence(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        try:
            cls.root = tk.Tk()
        except Exception:
            cls.root = None
            return
        cls.root.withdraw()
        _session(cls.root, legacy(module, LEGACY, 'settings_window'))   # 预热：首次建窗布局不同

    @classmethod
    def tearDownClass(cls):
        if cls.root is not None:
            cls.root.destroy()

    def setUp(self):
        if self.root is None:
            self.skipTest(PLATFORM_TKINTER)

    def test_matches_legacy(self):
        old = legacy(module, LEGACY, 'settings_window')
        self.assertEqual(_session(self.root, module.settings_window), _session(self.root, old))


if __name__ == '__main__':
    unittest.main()
